import{_ as o,o as e,c as a,ah as A}from"./chunks/framework.Cq2CPxk9.js";const n="/projects/AiNova/en/latest/assets/image3.DDEef5HT.webp",i="/projects/AiNova/en/latest/assets/image4.Bf5GlL1N.webp",s="/projects/AiNova/en/latest/assets/image5.CfZw4jc5.webp",r="/projects/AiNova/en/latest/assets/image6.BkzdjRnH.webp",g="/projects/AiNova/en/latest/assets/image7.B2t0kbxg.webp",l="/projects/AiNova/en/latest/assets/image8.CAfft9XR.webp",c="/projects/AiNova/en/latest/assets/image9.D83578Rz.webp",d="/projects/AiNova/en/latest/assets/image10.BP29WQlN.webp",m="/projects/AiNova/en/latest/assets/image11.CQ28U_gM.webp",p="/projects/AiNova/en/latest/assets/image12.BhkQWBJE.webp",h="data:image/png;base64,",u="/projects/AiNova/en/latest/assets/image14.DTP24JBM.webp",w="/projects/AiNova/en/latest/assets/image3.BkDPMLKM.webp",f="/projects/AiNova/en/latest/assets/image16.afuQWoHK.webp",b="data:image/png;base64,",E="/projects/AiNova/en/latest/assets/image3.Dop0pwZM.webp",C="data:image/png;base64,",V="data:image/png;base64,",q="data:image/png;base64,",S="data:image/png;base64,",W="data:image/png;base64,",R="data:image/png;base64,",K="data:image/png;base64,",v="data:image/png;base64,",x="data:image/png;base64,",I="data:image/png;base64,",N="data:image/png;base64,",P="data:image/png;base64,",k="data:image/png;base64,",y="data:image/png;base64,",B="/projects/AiNova/en/latest/assets/image18.XWR_S_Zi.webp",Q="/projects/AiNova/en/latest/assets/image19.DyjhfvpT.webp",U="/projects/AiNova/en/latest/assets/image20.BUS9_R0o.webp",G="/projects/AiNova/en/latest/assets/image21.BBKX0gR9.webp",J="/projects/AiNova/en/latest/assets/image22.BCUdivTS.webp",X="/projects/AiNova/en/latest/assets/image23.WbqJ6qFb.webp",O="/projects/AiNova/en/latest/assets/image24.DuEG9IY0.webp",M="data:image/png;base64,",F=JSON.parse('{"title":"2. Programming Software Installation","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2.programming_software_installation.md","filePath":"docs/2.programming_software_installation.md"}'),z={name:"docs/2.programming_software_installation.md"};function T(Y,t,D,Z,L,H){return e(),a("div",null,[...t[0]||(t[0]=[A('<h1 id="_2-programming-software-installation" tabindex="-1">2. Programming Software Installation <a class="header-anchor" href="#_2-programming-software-installation" aria-label="Permalink to &quot;2. Programming Software Installation&quot;">​</a></h1><h2 id="_2-1-wondercode-software-installation" tabindex="-1">2.1 WonderCode Software Installation <a class="header-anchor" href="#_2-1-wondercode-software-installation" aria-label="Permalink to &quot;2.1 WonderCode Software Installation&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>You can refer to the demonstration video in this section&#39;s folder.</p></div><h3 id="_2-1-1-introduction-to-the-programming-software" tabindex="-1">2.1.1 Introduction to the Programming Software <a class="header-anchor" href="#_2-1-1-introduction-to-the-programming-software" aria-label="Permalink to &quot;2.1.1 Introduction to the Programming Software&quot;">​</a></h3><p>WonderCode is a dedicated Scratch-based programming tool designed specifically for the AiNova robot for use with the CoreX controller. This software supports automatic conversion of graphical instruction blocks to Python code, making it ideal for beginners. Programming is done by simply dragging and dropping command blocks.</p><h3 id="_2-1-2-software-installation" tabindex="-1">2.1.2 Software Installation <a class="header-anchor" href="#_2-1-2-software-installation" aria-label="Permalink to &quot;2.1.2 Software Installation&quot;">​</a></h3><p>(1) Locate and open the installation file <strong>WonderCode setup.exe</strong> in the same directory as this document or in &quot;<a href="./Appendix.html"><strong>Apenndix -&gt;Software Installation Package &amp; Program Collection</strong></a>&quot;.</p><img loading="lazy" height="142" width="126" class="common_img" src="'+n+'"><p>(2) In the language selection window, choose English and click <strong>&quot;OK&quot;.</strong></p><img loading="lazy" height="164" width="353" class="common_img" src="'+i+'"><p>(3) Choose the installation location. You can either keep the default path or select a custom one, then click <strong>&quot;Next&quot;.</strong></p><img loading="lazy" height="417" width="586" class="common_img" src="'+s+'"><p>(4) In the Additional Tasks window, keep the default setting &quot;<strong>Create a desktop shortcut&quot;</strong> checked, then proceed.</p><img loading="lazy" height="417" width="586" class="common_img" src="'+r+'"><p>(5) Click <strong>&quot;Install&quot;</strong> to begin installation.</p><img loading="lazy" height="417" width="586" class="common_img" src="'+g+'"><p>(6) The software will begin installing and a progress bar will appear.</p><img loading="lazy" height="417" width="586" class="common_img" src="'+l+'"><p>(7) Once the installation is complete, a prompt will appear. Click <strong>&quot;Finish&quot;.</strong></p><img loading="lazy" height="417" width="586" class="common_img" src="'+c+'"><p>(8) A new WonderCode icon will appear on your desktop.</p><img loading="lazy" height="107" width="98" class="common_img" src="'+d+'"><h3 id="_2-1-3-device-connection" tabindex="-1">2.1.3 Device Connection <a class="header-anchor" href="#_2-1-3-device-connection" aria-label="Permalink to &quot;2.1.3 Device Connection&quot;">​</a></h3><p>(1) Use a USB data cable to connect the CoreX controller to your computer.</p><img loading="lazy" height="865" width="914" class="common_img" src="'+m+'"><p>(2) Double-click the WonderCode icon to launch the software. The main interface will appear.</p><img loading="lazy" height="893" width="1386" class="common_img" src="'+p+'"><p>(3) Before connecting the device, you must add the device extension pack. Otherwise, the connection will fail. Click the button <img loading="lazy" height="49" width="59" src="'+h+'"> in the bottom-left corner of the interface. In the pop-up window, navigate to and select <strong>&quot;Robot&quot; -&gt; &quot;AiNova&quot;.</strong></p><img loading="lazy" height="314" width="1383" class="common_img" src="'+u+'"><p>(4) Then click the <strong>&quot;Connect&quot;</strong> button on the main interface, and select the correct COM port.</p><img loading="lazy" height="141" width="449" class="common_img" src="'+w+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>The COM port number varies depending on your computer. For example, in this tutorial, the port is COM3. Do not select COM1, as it is typically reserved for system communication.</p></div><p>If multiple USB devices are connected and you&#39;re unsure of the correct port: Go to your desktop, right-click <strong>&quot;This PC&quot;</strong>, choose <strong>&quot;Properties&quot;</strong>, then open <strong>&quot;Device Manager&quot;</strong>. Check the AiNova robot controller under Ports (COM &amp; LPT). The correct port usually includes <strong>&quot;CH340&quot;</strong> in its name.</p><img loading="lazy" height="425" width="952" class="common_img" src="'+f+'"><p>(5) When the device is successfully connected, a <strong>&quot;Connect Success&quot;</strong> message will appear.</p><img loading="lazy" height="43" width="165" class="common_img" src="'+b+'"><h2 id="_2-2-interface-overview-and-program-download" tabindex="-1">2.2 Interface Overview and Program Download <a class="header-anchor" href="#_2-2-interface-overview-and-program-download" aria-label="Permalink to &quot;2.2 Interface Overview and Program Download&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>You can refer to the demonstration video in this section&#39;s folder.</p></div><h3 id="_2-2-1-function-button-introduction" tabindex="-1">2.2.1 Function Button Introduction <a class="header-anchor" href="#_2-2-1-function-button-introduction" aria-label="Permalink to &quot;2.2.1 Function Button Introduction&quot;">​</a></h3><p>The main interface of WonderCode is divided into four key sections, as shown in the figure below:</p><img loading="lazy" height="861" width="1384" class="common_img" src="'+E+'"><p>The corresponding functional areas for each number are shown in the table below：</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>No.</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;">①</td><td style="text-align:center;">Menu</td></tr><tr><td style="text-align:center;">②</td><td style="text-align:center;">Command block</td></tr><tr><td style="text-align:center;">③</td><td style="text-align:center;">Workspace</td></tr><tr><td style="text-align:center;">④</td><td style="text-align:center;">Code Display and Upload</td></tr></tbody></table><p>The buttons and their corresponding functions on the interface are shown in the table below:</p><table class="docutils-nobg" border="1"><colgroup><col><col></colgroup><tbody><tr><td><strong>Icon</strong></td><td><strong>Function</strong></td></tr><tr><td><img loading="lazy" height="38" width="73" class="common_img" src="'+C+'"></td><td>Build new file, save and open.</td></tr><tr><td><img loading="lazy" height="40" width="76" class="common_img" src="'+V+'"></td><td>Only used for the online mode.</td></tr><tr><td><img loading="lazy" height="36" width="160" class="common_img" src="'+q+'"></td><td>Determine whether to connect the device and software, and specify the connection port.</td></tr><tr><td><img loading="lazy" height="35" width="79" class="common_img" src="'+S+'"></td><td>Check tutorial, update and install drier.</td></tr><tr><td><img loading="lazy" height="51" width="184" class="common_img" src="'+W+'"></td><td>Display the program file name. If programming has not started or the file has not been saved, it shows Scratch Project.</td></tr><tr><td><img loading="lazy" height="46" width="252" class="common_img" src="'+R+'"></td><td><p>Interface Switching Button: Allows switching between &quot;<strong>Online Mode</strong>&quot; and &quot;<strong>Upload Mode</strong>&quot;.</p><p>Be sure to save the edited program file before switching; otherwise, unsaved changes may be lost.</p><p>Note: Online Mode is suitable for animations and games—features native to Scratch. Upload Mode must be used in conjunction with our hardware to enable various functional applications.</p></td></tr><tr><td><img loading="lazy" height="42" width="56" class="common_img" src="'+K+'"></td><td>Select the display language of the interface. You can switch between English, Simplified Chinese, and Traditional Chinese.</td></tr><tr><td><img loading="lazy" height="46" width="87" class="common_img" src="'+v+'"></td><td>Undone or redone during programming.</td></tr><tr><td><img loading="lazy" height="46" width="271" class="common_img" src="'+x+'"></td><td>Switch programming method. &quot;<strong>Auto</strong>&quot; converts the instruction block into Python form. Switch to &quot;<strong>Python Programming</strong>&quot; to directly use Python to edit the program.</td></tr><tr><td><img loading="lazy" height="45" width="49" class="common_img" src="'+I+'"></td><td>Save the program in the form of Python code.</td></tr><tr><td><img loading="lazy" height="47" width="52" class="common_img" src="'+N+'"></td><td>Open the saved Python file.</td></tr><tr><td><img loading="lazy" height="45" width="57" class="common_img" src="'+P+'"></td><td>Upload the programming into the controller.</td></tr><tr><td><img loading="lazy" height="50" width="61" class="common_img" src="'+k+'"></td><td>Used to add extension packages for devices.</td></tr><tr><td><img loading="lazy" height="156" width="67" class="common_img" src="'+y+'"></td><td>From top to bottom, the buttons control zooming in, zooming out, and resetting the code editor to its default size.</td></tr></tbody></table><h3 id="_2-2-2-programming-operation-method" tabindex="-1">2.2.2 Programming Operation Method <a class="header-anchor" href="#_2-2-2-programming-operation-method" aria-label="Permalink to &quot;2.2.2 Programming Operation Method&quot;">​</a></h3><p>This section explains how to use the WonderCode software by editing a program that makes the LED light on the main controller stay solid red. Steps:</p><p>(1) After the device is successfully connected, you can start writing the program. First, find the <strong>&quot;AiNova Program&quot;</strong> block in the AiNova command set and drag it into the code editing area.</p><img loading="lazy" height="476" width="727" class="common_img" src="'+B+'"><p>To delete a command block, drag it backward from the code editing area back to the command set area.</p><p>(2) Then drag the <strong>&quot;Forever&quot;</strong> block from the control commands set and attach it after the previous block.</p><img loading="lazy" height="453" width="629" class="common_img" src="'+Q+'"><p>(3) Next, drag the block to set LED color from the AiNova command and set into the <strong>&quot;Forever&quot;</strong> block. Select to set all LEDs to solid red.</p><img loading="lazy" height="515" width="767" class="common_img" src="'+U+'"><p>According to the RGB color principle, different combinations of the thresholds for red, green, and blue can produce various colors. The threshold range for each color is 0–255.</p><p>When one of the colors has a threshold of 255 and the other two are 0, the resulting color is that pure color. For example, in this section, to make the LED red, set the red threshold to 255, and blue and green thresholds to 0.</p><h3 id="_2-2-3-program-download" tabindex="-1">2.2.3 Program Download <a class="header-anchor" href="#_2-2-3-program-download" aria-label="Permalink to &quot;2.2.3 Program Download&quot;">​</a></h3><p>(1) Import the <a href="https://drive.google.com/drive/folders/12jUYlKAWNZz0T4Q1mNz6r6jR32CrrVe6?usp=sharing" target="_blank" rel="noreferrer">AiNova Bluetooth Control.sb3</a> program , or simply drag it onto the main interface of the programming software.</p><img loading="lazy" height="280" width="630" class="common_img" src="'+G+'"><img loading="lazy" height="441" width="814" class="common_img" src="'+J+'"><p>(2) After importing the program, click the <strong>&quot;Upload&quot;</strong> icon in the upper right corner of the interface.</p><img loading="lazy" height="237" width="1383" class="common_img" src="'+X+'"><img loading="lazy" height="402" width="1384" class="common_img" src="'+O+'"><p>(3) Wait for the download to complete; then you will see an <strong>&quot;Successful&quot;</strong> message.</p><img loading="lazy" height="41" width="122" class="common_img" src="'+M+'"><p>(4) You can then proceed to &quot;<a href="./4.app_remote_control.html"><strong>4. APP Remote Control</strong></a>&quot; to experience the feature.</p>',66)])])}const _=o(z,[["render",T]]);export{F as __pageData,_ as default};
